contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint lockTime, uint amount, uint collectAmount) public payable {
        require(address(this).balance >= amount);
        // Setup: put some balance with an unlock time in the past so it's collectible
        c.Put{value: amount}(lockTime);
        // Ensure MinSum is zero so Collect only needs balance >= collectAmount and time > unlockTime
        c.SetMinSum(0);

        (uint unlockBefore, uint balanceBefore) = c.Acc(address(this));

        // Only try to collect if the balance and locking conditions allow it; otherwise skip the call
        bool reverted;
        if (balanceBefore >= collectAmount && block.timestamp > unlockBefore) {
            try c.Collect(collectAmount) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // If conditions are not met, calling Collect would do nothing (no revert, no state change)
            c.Collect(collectAmount);
            reverted = false;
        }

        (uint unlockAfter, uint balanceAfter) = c.Acc(address(this));

        // General rule: if Collect succeeded and did not revert, and the collect amount was positive,
        // the recorded balance should have decreased by exactly collectAmount.
        // If conditions were not met, balance should remain unchanged.
        // Avoid underflow in subtraction by checking before >= after.
        if (!reverted && collectAmount > 0) {
            assert(balanceBefore >= balanceAfter);
            assert(balanceBefore - balanceAfter == collectAmount);
        } else {
            assert(balanceAfter == balanceBefore);
        }
    }

    receive() external payable {}
}

