contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address logAddr, uint val, uint lockTime, uint attemptCollect) public payable {
        // Setup: set log file and min sum before locking.
        c.SetLogFile(logAddr);
        c.SetMinSum(val);

        // Put ether from this contract into c for the sender.
        uint beforeBal = address(this).balance;
        require(beforeBal >= msg.value, "test must have enough balance");
        c.Put{value: msg.value}(lockTime);

        // Read c's observable balance for the sender after the put.
        uint afterPutBal = c.Acc(address(this)).balance;

        // Try to collect before the lock expires.
        bool collectReverted;
        uint collectAmount = attemptCollect;
        try c.Collect(collectAmount) {
            collectReverted = false;
        } catch {
            collectReverted = true;
        }

        // Read c's balance for the sender after attempting collect.
        uint afterCollectBal = c.Acc(address(this)).balance;

        // General rule: Put must have increased the sender's recorded balance by exactly msg.value,
        // and a failed Collect must not change the recorded balance.
        bool putOk = (afterPutBal == msg.value);
        bool collectOk = collectReverted ? (afterCollectBal == afterPutBal) : (afterCollectBal == afterPutBal - collectAmount);

        assert(putOk && collectOk);
    }

    receive() external payable {}
}

