        require(address(this).balance >= putAmount);
        require(putAmount > 0);

        // Setup: set a minimum sum and log file so that Put/Collect can run normally.
        c.SetMinSum(0);
        c.SetLogFile(address(this));

        c.Put{value: putAmount}(lockTime);

        (uint beforeUnlockTime, uint beforeBalance) = c.Acc(address(this));

