        try c.Collect(collectAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        (uint afterUnlockTime, uint afterBalance) = c.Acc(address(this));

        // General rule: Collect can never reduce the recorded balance below zero.
        // If it reverts, the balance must stay the same. If it succeeds, it must
        // subtract exactly collectAmount from the pre-call balance, except that
        // when collectAmount exceeds the balance the precondition prevents the
        // transfer and the balance must stay unchanged.
        assert(
            reverted
                ? afterBalance == beforeBalance
                : (collectAmount <= beforeBalance ? afterBalance == beforeBalance - collectAmount : afterBalance == beforeBalance)
        );
    }

    receive() external payable {}
}

