        uint tsBefore1 = block.timestamp;
        c.Put{value: putAmount1}(lockTime1);
        (uint unlockTime1, uint balance1) = c.Acc(address(this));

        // Timestamp before second Put
        uint tsBefore2 = block.timestamp;
        c.Put{value: putAmount2}(lockTime2);
        (uint unlockTime2, uint balance2) = c.Acc(address(this));

        // Timestamps after puts (block.timestamp is the same within the transaction)
        uint tsAfter = block.timestamp;

        // General rule: after two Puts, the recorded balance must equal the sum of all sent amounts plus initial balance
        assert(balance2 == oldBalance + putAmount1 + putAmount2);
        // Lock time must be at least the maximum of the two potential new unlock times
        assert(unlockTime2 >= tsBefore1 + lockTime1 && unlockTime2 >= tsBefore2 + lockTime2);
        // Lock time should be the maximum of oldUnlockTime and the new candidates, bounded by current timestamp
        assert(unlockTime2 >= oldUnlockTime && unlockTime2 <= tsAfter + (lockTime1 > lockTime2 ? lockTime1 : lockTime2));
    }

    receive() external payable {}
}

