        // Read before values.
        uint balBefore = 0;
        (balBefore, ) = c.Acc(address(this));
        uint testBalBefore = address(this).balance;

        // Deciding call: attempt to collect.
        bool collectOk;
        try c.Collect(collectAmount) {
            collectOk = true;
        } catch {
            collectOk = false;
        }

        // Read after values.
        uint balAfter = 0;
        (balAfter, ) = c.Acc(address(this));
        uint testBalAfter = address(this).balance;

        // General rule: successful Collect decreases Acc balance by exactly
        // the requested amount and sends the same Ether amount to the caller.
        assert(!collectOk || (balAfter == balBefore - collectAmount && testBalAfter == testBalBefore + collectAmount));
    }

    receive() external payable {}
}

